const $=id=>document.getElementById(id),C=MealCore;let allRows=[],allScope='',mode='real',metric='total',selected=null,map=null,layer=null;
const money=v=>v==null?'계산 불가':Math.round(v).toLocaleString('ko-KR')+'원';
const compact=v=>v==null?'미공개':v>=100000000?(v/100000000).toFixed(1)+'억':v>=10000?(v/10000).toLocaleString('ko-KR',{maximumFractionDigits:1})+'만':Math.round(v).toLocaleString('ko-KR');
const safe=s=>String(s??'미공개').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function rows(){return C.filter(mode==='demo'?C.demoRows():allRows,{search:$('search').value.trim(),period:$('period').value,institution:$('institution').value,region:$('region').value,category:$('category').value});}
function options(id,values){const old=$(id).value;$(id).replaceChildren(new Option(id==='period'?'전체 기간':id==='institution'?'전체 기관':'전체 지역','all'),...values.map(v=>new Option(v,v)));if(values.includes(old))$(id).value=old;}
function setMode(next){mode=next;selected=null;$('detail').hidden=true;$('real').classList.toggle('active',next==='real');$('demo').classList.toggle('active',next==='demo');const r=next==='demo'?C.demoRows():allRows;options('period',[...new Set(r.map(r=>(r.date||'').slice(0,7)).filter(Boolean))].sort().reverse());options('institution',[...new Set(r.map(r=>r.institution))].sort());options('region',Object.keys(C.regions));$('mode-note').textContent=next==='demo'?'화면 체험 중 · 기관·식당·금액·위치 모두 가상 자료입니다.':'수집 범위: '+allScope+' 미수집은 지출 0원이 아닙니다.';$('legend-label').textContent=next==='demo'?'가상 지출 · 실제 자료 아님':'공개자료의 지출액';render();}
function render(){const r=rows(),s=C.stats(r);$('total').innerHTML=Number(s.total).toLocaleString('ko-KR')+'<em>원</em>';$('count').textContent=s.count.toLocaleString()+'건';$('per-person').textContent=money(s.perPerson);$('coverage').textContent=`지도 사용처 ${C.group(r.filter(x=>x.location),x=>x.location.lat+'|'+x.location.lng).length.toLocaleString()}곳 · 인당 계산 ${s.knownCount}건 · 기재 연인원 ${s.people}명 · 지역 확인 ${r.filter(x=>x.spending_region).length}건 · 좌표 확인 ${r.filter(x=>x.location).length}건 / ${r.length}건`;$('results-title').textContent=`집행 내역 ${s.count}건${s.count>200?' · 금액 상위 200건 표시':''}`;$('results').replaceChildren();r.slice().sort((a,b)=>b.amount_krw-a.amount_krw).slice(0,200).forEach(x=>{const el=document.createElement('button');el.className='result';el.innerHTML=`<div class="result-top"><h3>${safe(x.merchant)}</h3><span class="amount">${money(x.amount_krw)}</span></div><div class="metadata">${safe(x.institution)} · ${safe(x.department)}<br>${safe(x.date)} · 기재 ${x.participants??'미공개'}명</div><span class="badge">${safe(x.category)}</span>${!x.location?'<span class="badge pending">위치 확인 대기</span>':''}<span class="per-person">1인당 ${money(x.participants>0?x.amount_krw/x.participants:null)}</span>`;el.onclick=()=>show([x]);$('results').append(el);});if(!r.length)$('results').innerHTML='<div class="empty">조건에 맞는 공개자료가 없습니다.<br>기간이나 기관 필터를 바꿔 보세요.</div>';draw(r);}
function focusRegion(items,fallback){const points=items.filter(r=>r.location).map(r=>[r.location.lat,r.location.lng]);if(points.length)map.fitBounds(L.latLngBounds(points).pad(.25),{maxZoom:12,padding:[55,90]});else map.setView(fallback,10);}
function draw(r){if(!map)return;layer.clearLayers();const isClose=map.getZoom()>=9;$('zoom-label').textContent=isClose?'식당별 지출 · 실제 좌표':'지역별 지출';$('map-help').textContent=isClose?'식당을 누르면 기관·날짜·인원·인당 비용을 확인할 수 있어요.':'지역을 누르거나 지도를 확대하면 식당별로 볼 수 있어요.';const groups=isClose?C.group(r.filter(x=>x.location),x=>x.location.lat+'|'+x.location.lng):C.group(r,x=>x.spending_region);groups.forEach(g=>{const coord=isClose?[g.rows[0].location.lat,g.rows[0].location.lng]:C.regions[g.key];if(!coord)return;const val=metric==='total'?g.total:g.perPerson;const placeNames=[...new Set(g.rows.map(r=>r.merchant))];const placeLabel=placeNames.length>1?placeNames.length+'개 사용처 · 같은 주소':placeNames[0];const icon=L.divIcon({className:'money-marker',iconSize:[0,0],html:`<button class="pin ${isClose?'restaurant':''}" aria-label="${safe(g.rows[0].demo?'가상 자료 ': '')}${safe(isClose?placeLabel:g.key)} ${safe(money(val))}"><span>${safe(isClose?placeLabel:g.key)}</span><b>${compact(val)}${val==null?'':'원'}</b></button>`});const marker=isClose?L.circleMarker(coord,{radius:map.getZoom()>=14?6:4,color:'#ffffff',weight:1,fillColor:'#205b46',fillOpacity:.85}).bindTooltip(safe(placeLabel)+' · '+money(val),{direction:'top',permanent:map.getZoom()>=16}):L.marker(coord,{icon,keyboard:true});marker.addTo(layer).on('click',()=>{if(!isClose){$('region').value=g.key;focusRegion(g.rows,coord);render();if(!g.rows.some(r=>r.location))show(g.rows);}else show(g.rows);});});if(!isClose){Object.entries(C.regions).forEach(([name,coord])=>{if(r.some(x=>x.spending_region===name))return;L.marker(coord,{icon:L.divIcon({className:'money-marker',iconSize:[0,0],html:`<button class="pin uncollected"><span>${safe(name)}</span><b>${$('region').value==='all'?'미수집/조건 없음':'조건 없음'}</b></button>`})}).addTo(layer).on('click',()=>{$('region').value=name;map.setView(coord,10);render();});});}if(isClose&&!r.some(x=>x.location))$('map-help').textContent='이 범위의 식당 좌표는 확인 대기 중입니다. 왼쪽 목록에서 원문 지출을 볼 수 있어요.';}
function show(items){selected=items;const s=C.stats(items),x=items[0];$('detail').hidden=false;$('detail').innerHTML=`<button class="close-detail" aria-label="상세 닫기">×</button><div class="eyebrow">${mode==='demo'?'SAMPLE DATA · 가상 자료':'DISCLOSED SPENDING · 공개자료'}</div><h2>${safe(items.length===1?x.merchant:items.every(r=>r.merchant===x.merchant)?x.merchant:[...new Set(items.map(r=>r.merchant))].length+'개 사용처 집행 내역')}</h2><p>${safe((x.address||'사용처의 정확한 주소는 확인 대기 중입니다.')+(x.location?.precision==='address'?' · 지도는 주소·건물 기준 위치':''))}</p><div class="detail-total">${money(s.total)}</div><div class="detail-grid"><div>공개 집행<b>${s.count}건</b></div><div>기재 연인원<b>${s.people}명</b></div><div>기재 기준 인당<b>${money(s.perPerson)}</b></div></div>${items.slice().sort((a,b)=>(b.date||'').localeCompare(a.date||'')).slice(0,200).map(r=>`<article><strong>${safe(r.institution)} · ${safe(r.department)}</strong><p>${safe(r.date)} · ${safe(r.category)} · ${safe(r.payment_method)}<br>${safe(r.purpose)}<br>${safe(r.participant_text)}<br>집행액 ${money(r.amount_krw)} · 1인당 ${money(r.participants>0?r.amount_krw/r.participants:null)}</p>${r.source_url&&/^https:\/\//.test(r.source_url)?`<a href="${safe(r.source_url)}" target="_blank" rel="noopener">공개 원문에서 확인 ↗</a>`:'<span class="per-person">가상 자료 · 실제 지출이 아닙니다</span>'}</article>`).join('')}<p>${items.length>200?'건별 상세는 최근 200건을 표시합니다. ':''}인원은 공개자료 기재값입니다. 실제 참석 여부를 검증한 값이 아닙니다.${!x.location?' 식당 지점·좌표 확인 후 지도에 표시합니다.':''}</p>`;$('detail').querySelector('.close-detail').onclick=()=>$('detail').hidden=true;if(items.length===1&&x.location&&map)map.setView([x.location.lat,x.location.lng],14);}
['search','period','institution','region','category'].forEach(id=>$(id).addEventListener(id==='search'?'input':'change',()=>{selected=null;$('detail').hidden=true;if(id==='region'&&map&&C.regions[$(id).value])focusRegion(rows(),C.regions[$(id).value]);render();}));
$('real').onclick=()=>setMode('real');$('demo').onclick=()=>setMode('demo');$('metric-total').onclick=()=>setMetric('total');$('metric-person').onclick=()=>setMetric('person');function setMetric(m){metric=m;$('metric-total').classList.toggle('active',m==='total');$('metric-person').classList.toggle('active',m==='person');render();}
$('reset-map').onclick=()=>{$('region').value='all';if(map)map.setView([36.1,127.8],7);render();};$('about').onclick=()=>$('info').showModal();$('close-info').onclick=()=>$('info').close();$('info').onclick=e=>{if(e.target===$('info'))$('info').close();};
$('export').onclick=()=>{const keys=['date','institution','department','merchant','spending_region','purpose','amount_krw','participants','per_person_krw','source_url'];const cell=v=>'"'+String(v??'').replace(/^[=+@\-]/,"'$&").replace(/"/g,'""')+'"';const csv='\ufeff'+[keys,...rows().map(r=>keys.map(k=>k==='per_person_krw'?(r.participants>0?Math.round(r.amount_krw/r.participants):null):r[k]))].map(a=>a.map(cell).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=mode==='demo'?'가상자료-실제지출아님.csv':'공개업무추진비.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
if(typeof L!=='undefined'){map=L.map('map',{zoomControl:false,preferCanvas:true,minZoom:6,maxZoom:18}).setView([36.1,127.8],7);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>',maxZoom:19}).addTo(map);L.control.zoom({position:'bottomright'}).addTo(map);layer=L.layerGroup().addTo(map);map.on('zoomend',()=>draw(rows()));}else{$('map-help').textContent='지도를 불러오지 못했습니다. 지출 목록은 계속 볼 수 있습니다.';}
fetch('data.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error('자료를 불러오지 못했습니다');return r.json();}).then(async data=>{if(data.full_data){if(typeof DecompressionStream==='undefined'){data.scope='이 브라우저는 압축 이력을 지원하지 않아 최신 '+data.records.length+'건만 표시합니다.';}else{const response=await fetch(data.full_data,{cache:'no-store'});if(!response.ok)throw Error('이력 로딩 실패');const bytes=new Uint8Array(await response.arrayBuffer());const text=bytes[0]===31&&bytes[1]===139?await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).text():new TextDecoder().decode(bytes);data=C.unpackSnapshot(JSON.parse(text));}}allRows=data.records;allScope=data.scope||'수집 범위 확인 중';$('updated').textContent='수집 '+new Date(data.updated_at).toLocaleDateString('ko-KR',{timeZone:'Asia/Seoul'});setMode('real');const requestedRegion=new URLSearchParams(location.search).get('region');if(requestedRegion&&C.regions[requestedRegion]){$('region').value=requestedRegion;if(map)focusRegion(rows(),C.regions[requestedRegion]);render();}const failed=(data.source_status||[]).filter(s=>s.status==='failed');if(failed.length)$('mode-note').textContent+=' 일부 출처 '+failed.length+'건 갱신 실패: 기존 자료 유지.';}).catch(()=>{$('mode-note').textContent='실자료 파일을 불러오지 못했습니다. 새로고침하거나 화면 체험을 이용하세요.';$('updated').textContent='데이터 로딩 실패';});
